    if status not in _PA_STATUSES:
        raise _prune_aggregate_chain_invalid("payload status is not a known status")
    declaration = _validated_aggregate_chain_declaration(payload[PBA_DECLARATION], "payload declaration")
    declaration_digest = payload[PAC_DECLARATION_DIGEST]
    if declaration is None:
