            raise _prune_aggregate_chain_invalid("a null common declaration binds no declaration digest")
    else:
        if not isinstance(declaration_digest, str):
            raise TypeError("payload declarationDigest must be a str")
        if not _prune_is_digest(declaration_digest):
            raise _prune_aggregate_chain_invalid("payload declarationDigest must be 64 lowercase hex characters")
        if declaration_digest != _aggregate_declaration_digest(declaration):
            raise _prune_aggregate_chain_invalid("payload declarationDigest does not match the common declaration")
